import numpy as np, itertools
t=df['t'];P=df['P'];y=df['dP_dt']
Pf={'P':P,'P2':P**2,'sqP':np.sqrt(P),'1':np.ones_like(P),'logP':np.log(P),'1/P':1/P,'P3':P**3,'expP':np.exp(-P),'P1.5':P**1.5}
tf={'t':t,'t2':t**2,'exp-t':np.exp(-t),'exp-t2':np.exp(-t**2),'cos t':np.cos(t),'sin t':np.sin(t),'sqt':np.sqrt(t),'logt':np.log(t),'1/t':1/t,'exp-0.5t':np.exp(-0.5*t),'1':np.ones_like(t),'cos2t':np.cos(2*t),'sin2t':np.sin(2*t)}
names=[];cols=[]
for pn,pv in Pf.items():
    for tn,tv in tf.items():
        names.append(pn+'*'+tn);cols.append(pv*tv)
