    names.append(pn);cols.append(pv)
for tn,tv in tf.items():
    names.append(tn);cols.append(tv)
Bp=np.column_stack(cols); K=Bp.shape[1]
I,J=np.triu_indices(K,1)
vy=np.var(y); n=len(y)
best=(1e9,)
for a in np.linspace(0.2,4,39):
    s=np.sin(a*np.sqrt(P))
    X=np.column_stack([np.repeat(s[:,None],1,1)[:,0],Bp])  # s + all
    G=X.T@X; b=X.T@y
    # pairs: indices 0 (s), i+1, j+1
    ii=np.stack([np.zeros(len(I),int),I+1,J+1],1)
